// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type StepCycleProps = Record<string, any>;

const StepCycle: React.FC<StepCycleProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 8,
  textColor = "#ffffff",
  dotColor = "#ffffff",
  lineColor = "rgba(255, 255, 255, 0.4)",
  items = ["Signup", "Setup", "Aha Moment", "Habit"],
  radiusScale = 0.35,
  fontSize = 38,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout parameters
  const minDim = Math.min(width, height);
  const R = minDim * radiusScale;
  const C = 2 * Math.PI * R;

  const N = items.length;
  const safeN = Math.max(2, N);

  // Timing calculations
  const durationInFrames = durationInSeconds * fps;
  const reserveFrames = 40; // Hold at the end
  const activeFrames = Math.max(60, durationInFrames - reserveFrames);
  const framesPerItem = activeFrames / safeN;

  // Determine split between text reveal and line drawing for each segment
  const nodeRevealDuration = Math.max(1, Math.min(15, framesPerItem * 0.3));
  const segmentDrawDuration = Math.max(1, framesPerItem - nodeRevealDuration);

  // Construct interpolation arrays safely
  const interpolateInput: number[] = [0];
  const interpolateOutput: number[] = [0];

  for (let i = 0; i < N; i++) {
    const revealStart = 20 + i * framesPerItem;
    const segmentStart = revealStart + nodeRevealDuration;
    const segmentEnd = segmentStart + segmentDrawDuration;

    const progressBefore = i / N;
    const progressAfter = (i + 1) / N;

    const prevTime = interpolateInput[interpolateInput.length - 1];
    
    // Ensure strict monotonicity for interpolate inputs
    const safeSegmentStart = Math.max(prevTime + 1, segmentStart);
    const safeSegmentEnd = Math.max(safeSegmentStart + 1, segmentEnd);

    interpolateInput.push(safeSegmentStart);
    interpolateOutput.push(progressBefore);

    interpolateInput.push(safeSegmentEnd);
    interpolateOutput.push(progressAfter);
  }

  // Fallback for empty lists to avoid crash
  const safeInput = interpolateInput.length > 1 ? interpolateInput : [0, 1];
  const safeOutput = interpolateOutput.length > 1 ? interpolateOutput : [0, 1];

  const lineProgress = interpolate(frame, safeInput, safeOutput, {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const strokeDashoffset = C - C * lineProgress;

  // Node positioning
  const nodes = items.map((label, i) => {
    // Start at Top (-PI/2) and distribute evenly
    const angle = -Math.PI / 2 + (i * 2 * Math.PI) / safeN;
    const x = width / 2 + R * Math.cos(angle);
    const y = height / 2 + R * Math.sin(angle);
    return { label, x, y, angle };
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* SVG Path Layer */}
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          overflow: "visible",
        }}
      >
        <defs>
          <mask id="drawing-mask">
            {/* The sweeping arc that reveals the path */}
            <circle
              cx={width / 2}
              cy={height / 2}
              r={R}
              fill="none"
              stroke="white"
              strokeWidth={20} // Thick enough to cover the dotted line entirely
              strokeDasharray={C}
              strokeDashoffset={strokeDashoffset}
              transform={`rotate(-90 ${width / 2} ${height / 2})`}
            />

            {/* Punch holes in the mask where the text nodes are to create gaps in the line */}
            {nodes.map((node, i) => {
              const rectWidth = Math.max(80, node.label.length * fontSize * 0.6);
              const rectHeight = fontSize * 2.5;
              return (
                <rect
                  key={`hole-${i}`}
                  x={node.x - rectWidth / 2}
                  y={node.y - rectHeight / 2}
                  width={rectWidth}
                  height={rectHeight}
                  fill="black"
                />
              );
            })}
          </mask>
        </defs>

        {/* The underlying dotted circle */}
        <circle
          cx={width / 2}
          cy={height / 2}
          r={R}
          fill="none"
          stroke={lineColor}
          strokeWidth={3}
          strokeDasharray="8 12"
          mask="url(#drawing-mask)"
        />
      </svg>

      {/* HTML Elements Layer (Dots & Text) */}
      {nodes.map((node, i) => {
        const revealStart = 20 + i * framesPerItem;

        // Dot scales in, then scales out when text reveals
        const dotScaleIn = spring({
          fps,
          frame: frame - i * 5,
          config: { damping: 12 },
        });
        const dotScaleOut = interpolate(
          frame,
          [revealStart, revealStart + 10],
          [1, 0],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );
        const dotScale = Math.max(0, dotScaleIn * dotScaleOut);

        // Text scales and fades in to replace the dot
        const textScale = spring({
          fps,
          frame: frame - revealStart,
          config: { damping: 14 },
        });
        const textOpacity = interpolate(
          frame,
          [revealStart, revealStart + 10],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        return (
          <div
            key={`node-${i}`}
            style={{
              position: "absolute",
              left: node.x,
              top: node.y,
              transform: `translate(-50%, -50%)`,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              transition: "none",
            }}
          >
            {/* Initial Dot */}
            <div
              style={{
                position: "absolute",
                width: fontSize * 0.4,
                height: fontSize * 0.4,
                backgroundColor: dotColor,
                borderRadius: "50%",
                transform: `scale(${dotScale})`,
                opacity: dotScale > 0.01 ? 1 : 0,
                transition: "none",
              }}
            />

            {/* Revealed Text */}
            <div
              style={{
                transform: `scale(${Math.max(0, textScale)})`,
                opacity: textOpacity,
                color: textColor,
                fontSize,
                fontWeight: 600,
                letterSpacing: "-0.02em",
                whiteSpace: "nowrap",
                fontFamily: interFamily,
                transition: "none",
              }}
            >
              {node.label}
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default StepCycle;